-- Audited content only. Holds remain owner-only records, never published theories.
select pg_advisory_xact_lock(hashtextextended('theory-knowledge-network',0));
lock table public.theories,public.techniques,public.theory_relations in share row exclusive mode;
-- Refuse to overwrite intervening editorial changes, even when counts are unchanged.
do $check$ begin
 if (select count(*) from public.theories where status='published')<>803 then raise exception 'Published catalogue changed; take a new backup and review.';end if;
 if (select md5(string_agg((to_jsonb(t)-'updated_at'-'updated_by')::text,'|' order by id)) from public.theories t where status='published') is distinct from 'ec7717144a9a94e73ea955792ed480ec' then raise exception 'Reviewed source changed; content migration aborted.';end if;
 if exists(select 1 from jsonb_to_recordset('[{"id":"master336-188","theory_ids":["kb_545"],"primary_theory_ids":["kb_545"]},{"id":"master336-195","theory_ids":["kb_181"],"primary_theory_ids":["kb_181"]},{"id":"master336-196","theory_ids":["kb_192"],"primary_theory_ids":["kb_192"]},{"id":"master336-198","theory_ids":["kb_087","kb_939","kb_941"],"primary_theory_ids":["kb_087"]},{"id":"master336-202","theory_ids":["kb_205","kb_952"],"primary_theory_ids":["kb_205"]},{"id":"master336-203","theory_ids":["kb_449","kb_622","kb_929","kb_931"],"primary_theory_ids":["kb_449"]},{"id":"master336-204","theory_ids":["kb_217","kb_625","kb_929","kb_930","kb_934","kb_937"],"primary_theory_ids":["kb_217"]},{"id":"master336-206","theory_ids":["kb_217","kb_625","kb_930","kb_950"],"primary_theory_ids":["kb_217"]},{"id":"master336-207","theory_ids":["kb_449","kb_933","kb_938"],"primary_theory_ids":["kb_449"]},{"id":"master336-225","theory_ids":["kb_108","kb_152"],"primary_theory_ids":["kb_108"]},{"id":"master336-230","theory_ids":["kb_153"],"primary_theory_ids":["kb_153"]},{"id":"master336-233","theory_ids":["kb_416","kb_523"],"primary_theory_ids":["kb_416"]},{"id":"master336-238","theory_ids":["kb_084","kb_161"],"primary_theory_ids":["kb_084"]}]'::jsonb) x(id text,theory_ids jsonb,primary_theory_ids jsonb) join public.techniques t using(id) where (t.theory_ids,t.primary_theory_ids) is distinct from (x.theory_ids,x.primary_theory_ids)) then raise exception 'Reviewed work links changed; content migration aborted.';end if;
end $check$;
insert into private.theory_reform_backups(phase,source_table,source_id,snapshot)
select 'reviewed-content-20261015','theories',id,to_jsonb(t) from public.theories t on conflict do nothing;
insert into private.theory_reform_backups(phase,source_table,source_id,snapshot)
select 'reviewed-content-20261015','techniques',id,to_jsonb(t) from public.techniques t on conflict do nothing;
insert into private.theory_reform_backups(phase,source_table,source_id,snapshot)
select 'reviewed-content-20261015','theory_relations',source_id||'|'||target_id,to_jsonb(t) from public.theory_relations t on conflict do nothing;
create or replace function public.validate_quotation_metadata() returns trigger language plpgsql set search_path='' as $fn$
declare q jsonb; f text;
begin
 if new.status<>'published' or (new.knowledge_type<>'aphorism' and new.quotation is null) then return new;end if;
 q:=new.quotation;
 if q is null or q->>'verification' is distinct from 'verified' or q->>'rightsStatus' is distinct from 'cleared' then
 raise exception '原典と権利の確認が済むまで格言は公開できません。' using errcode='23514';end if;
 foreach f in array array['originalText','translationText','author','work','locator','rightsBasis'] loop
 if nullif(trim(q->>f),'') is null then raise exception '格言の監査記録が不足しています: %',f using errcode='23514';end if;end loop;
 if coalesce(q->>'authorDeathYear','') !~ '^-?[0-9]+$' or coalesce(q->>'publicationYear','') !~ '^[0-9]+$' then
 raise exception '死亡年・刊行年を確認してください。' using errcode='23514';end if;
 if (q->>'authorDeathYear')::integer>1950 or (q->>'publicationYear')::integer>1950 then
 raise exception '今回の格言の権利審査対象外です。' using errcode='23514';end if;
 if coalesce(q->>'translationKind','') not in('original_japanese','independent_translation','classical_transcription')
 or coalesce(q->>'checkedOn','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
 or jsonb_typeof(q->'sourceUrls') is distinct from 'array' then raise exception '翻訳区分・確認日・資料が必要です。' using errcode='23514';end if;
 if jsonb_array_length(q->'sourceUrls')=0 or exists(select 1 from jsonb_array_elements_text(q->'sourceUrls') u where u !~ '^https://[^[:space:]]+$') then
 raise exception '原典の確認資料URLが必要です。' using errcode='23514';end if;
 if new.access_tier='complete' and replace(replace(new.title,'「',''),'」','')=q->>'translationText' then raise exception '完全版の格言本文は公開見出しと分けてください。' using errcode='23514';end if;
 new.summary:='「'||(q->>'translationText')||'」'||chr(10)||'— '||(q->>'author')||chr(10)||(q->>'work')||chr(10)||chr(10)||coalesce(q->>'contextNote','');
 return new;
end $fn$;

