 values('theory-e634c0c0-8300-44e5-a28f-916300973eb1','自分という欺きやすい相手','自分の動機や善良さへの確信も、自己欺瞞から自由ではないと刺す台詞。話者の応答と、相手がそれをどう受け取るかの落差も含めて読む。','classics-thought','古典・思想','classics-thought-f',10,'theory-e634c0c0-8300-44e5-a28f-916300973eb1','[]','[]','[]','published',80,80,'complete','aphorism','{"candidateId":"22","originalText":"the easiest person to deceive is one''s own self.","translationText":"いちばんだましやすい相手は、自分自身だ。","author":"ブルワー＝リットン","authorDeathYear":1873,"work":"The Disowned（勘当された者）","locator":"第4巻、グレンドワーがクローフォードに答える箇所","publicationYear":1828,"originalLanguage":"en","translationKind":"independent_translation","verification":"verified","rightsStatus":"cleared","rightsBasis":"著者1873年没、原語作品は1828年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","sourceUrls":["https://www.gutenberg.org/cache/epub/7634/pg7634.html"],"checkedOn":"2026-10-15","contextNote":"自分の動機や善良さへの確信も、自己欺瞞から自由ではないと刺す台詞。話者の応答と、相手がそれをどう受け取るかの落差も含めて読む。"}'::jsonb,'{"status":"確認済み","attribution":"ブルワー＝リットン","period":"1828年（原典・参照版）","works":["The Disowned（勘当された者）"],"sources":[{"title":"The Disowned（勘当された者）（原典本文）","url":"https://www.gutenberg.org/cache/epub/7634/pg7634.html"}],"note":"原語本文を照合した独自訳。 文学的・思想的な洞察であり、実証的な証拠とは区別する。"}'::jsonb);
insert into public.theories(id,title,summary,category_id,category_title,subcategory_id,taxonomy_order,canonical_id,legacy_ids,aliases,related_theory_ids,status,display_id,display_order,access_tier,knowledge_type,quotation,provenance)
 values('theory-e1df3caa-9877-4eed-a549-162cc3bdaca0','恋愛の詩的表現','欲望が言葉や想像によって恋愛へ姿を変えるという、皮肉を含む見方。続く原文は、詩的表現を受けない性欲は恋愛と呼ぶに値しないと述べる。','classics-thought','古典・思想','classics-thought-f',11,'theory-e1df3caa-9877-4eed-a549-162cc3bdaca0','[]','[]','[]','published',81,81,'complete','aphorism','{"candidateId":"26","originalText":"恋愛は唯性慾の詩的表現を受けたものである。少くとも詩的表現を受けない性慾は恋愛と呼ぶに価いしない。","translationText":"恋愛はただ性欲の詩的表現を受けたものである。","author":"芥川龍之介","authorDeathYear":1927,"work":"侏儒の言葉","locator":"「恋愛」、冒頭2文のうち第1文を表記整理して表示","publicationYear":1927,"originalLanguage":"ja","translationKind":"classical_transcription","verification":"verified","rightsStatus":"cleared","rightsBasis":"著者1927年没。日本語原著は1927年までに公表済み。旧法の死後50年期間が2018年以前に満了し復活しない。日本著作物のため戦時加算なし。底本の新しい解説・校注を使用しない。","sourceUrls":["https://www.aozora.gr.jp/cards/000879/files/158_15132.html"],"checkedOn":"2026-10-15","contextNote":"欲望が言葉や想像によって恋愛へ姿を変えるという、皮肉を含む見方。続く原文は、詩的表現を受けない性欲は恋愛と呼ぶに値しないと述べる。"}'::jsonb,'{"status":"確認済み","attribution":"芥川龍之介","period":"1927年（原典・参照版）","works":["侏儒の言葉"],"sources":[{"title":"侏儒の言葉（原典本文）","url":"https://www.aozora.gr.jp/cards/000879/files/158_15132.html"}],"note":"原文を照合し、表記整理した箇所は原文を別記。 文学的・思想的な洞察であり、実証的な証拠とは区別する。"}'::jsonb);
insert into public.theories(id,title,summary,category_id,category_title,subcategory_id,taxonomy_order,canonical_id,legacy_ids,aliases,related_theory_ids,status,display_id,display_order,access_tier,knowledge_type,quotation,provenance)
 values('theory-acb4311e-b6ca-416c-8d06-06cff53444b2','恋の飢えと充足','恋が満たされないことで続き、充足によって衰えるという逆説を詠む。恋愛相手を意図的に不安にさせる手法や、関係の普遍法則としては扱わない。','classics-thought','古典・思想','classics-thought-f',12,'theory-acb4311e-b6ca-416c-8d06-06cff53444b2','[]','[]','[]','published',82,82,'complete','aphorism','{"candidateId":"27","originalText":"L’amour (hélas ! l’étrange et la fausse nature !) Vit d’inanition, et meurt de nourriture.","translationText":"恋は飢えによって生き、食べ物を与えられて死ぬ。","author":"アルフレッド・ド・ミュッセ","authorDeathYear":1857,"work":"マルドッシュ（初期詩集）","locator":"第16節、末尾2行","publicationYear":1829,"originalLanguage":"fr","translationKind":"independent_translation","verification":"verified","rightsStatus":"cleared","rightsBasis":"著者1857年没、原語作品は1829年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","sourceUrls":["https://fr.wikisource.org/wiki/Premières_Poésies_(Musset,_éd._1863)/Mardoche"],"checkedOn":"2026-10-15","contextNote":"恋が満たされないことで続き、充足によって衰えるという逆説を詠む。恋愛相手を意図的に不安にさせる手法や、関係の普遍法則としては扱わない。"}'::jsonb,'{"status":"確認済み","attribution":"アルフレッド・ド・ミュッセ","period":"1829年（原典・参照版）","works":["マルドッシュ（初期詩集）"],"sources":[{"title":"マルドッシュ（初期詩集）（原典本文）","url":"https://fr.wikisource.org/wiki/Premières_Poésies_(Musset,_éd._1863)/Mardoche"}],"note":"原語本文を照合した独自訳。 文学的・思想的な洞察であり、実証的な証拠とは区別する。"}'::jsonb);
