 values('theory-4e128612-e3f0-4eb9-9c09-e3503466521d','友に自分を与える','友情を、相手を自分に従わせる関係とは反対のものとして語る。無制限な自己犠牲や、相手の要求をすべて引き受けることとは分けて読む。','classics-thought','古典・思想','classics-thought-p',23,'theory-4e128612-e3f0-4eb9-9c09-e3503466521d','[]','[]','[]','published',87,87,'complete','aphorism','{"candidateId":"43","originalText":"En la vraye amitié, de laquelle je suis expert, je me donne à mon amy plus que je ne le tire à moy.","translationText":"真の友情では、友を自分へ引き寄せる以上に、自分を友に与える。","author":"モンテーニュ","authorDeathYear":1592,"work":"エセー","locator":"第3巻第9章「虚栄について」","publicationYear":1588,"originalLanguage":"fr","translationKind":"independent_translation","verification":"verified","rightsStatus":"cleared","rightsBasis":"著者1592年没、原語作品は1588年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","sourceUrls":["https://fr.wikisource.org/wiki/Page:Montaigne_-_Essais,_Éd_de_Bordeaux,_3.djvu/174"],"checkedOn":"2026-10-15","contextNote":"友情を、相手を自分に従わせる関係とは反対のものとして語る。無制限な自己犠牲や、相手の要求をすべて引き受けることとは分けて読む。"}'::jsonb,'{"status":"確認済み","attribution":"モンテーニュ","period":"1588年（原典・参照版）","works":["エセー"],"sources":[{"title":"エセー（原典本文）","url":"https://fr.wikisource.org/wiki/Page:Montaigne_-_Essais,_Éd_de_Bordeaux,_3.djvu/174"}],"note":"原語本文を照合した独自訳。 文学的・思想的な洞察であり、実証的な証拠とは区別する。"}'::jsonb);
insert into public.theories(id,title,summary,category_id,category_title,subcategory_id,taxonomy_order,canonical_id,legacy_ids,aliases,related_theory_ids,status,display_id,display_order,access_tier,knowledge_type,quotation,provenance)
 values('theory-8cd3b27e-6948-4ad0-b961-46eb047b1b67','友情における疑い','裏切られる損より、疑いによって友情を損なう恥を強く置いた箴言。相手の危険な言動を無視する指示や、無条件の信用を証明する理論ではない。','classics-thought','古典・思想','classics-thought-p',24,'theory-8cd3b27e-6948-4ad0-b961-46eb047b1b67','[]','[]','[]','published',88,88,'complete','aphorism','{"candidateId":"44","originalText":"Il est plus honteux de se défier de ses amis que d’en être trompé.","translationText":"友人を疑うことは、友人にだまされることより恥ずかしい。","author":"ラ・ロシュフコー","authorDeathYear":1680,"work":"箴言集","locator":"第84箴言（1817年版）","publicationYear":1817,"originalLanguage":"fr","translationKind":"independent_translation","verification":"verified","rightsStatus":"cleared","rightsBasis":"著者1680年没、原語作品は1817年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","sourceUrls":["https://fr.wikisource.org/wiki/Maximes_et_Réflexions_morales/Réflexions_morales"],"checkedOn":"2026-10-15","contextNote":"裏切られる損より、疑いによって友情を損なう恥を強く置いた箴言。相手の危険な言動を無視する指示や、無条件の信用を証明する理論ではない。"}'::jsonb,'{"status":"確認済み","attribution":"ラ・ロシュフコー","period":"1817年（原典・参照版）","works":["箴言集"],"sources":[{"title":"箴言集（原典本文）","url":"https://fr.wikisource.org/wiki/Maximes_et_Réflexions_morales/Réflexions_morales"}],"note":"原語本文を照合した独自訳。 文学的・思想的な洞察であり、実証的な証拠とは区別する。"}'::jsonb);
insert into public.theories(id,title,summary,category_id,category_title,subcategory_id,taxonomy_order,canonical_id,legacy_ids,aliases,related_theory_ids,status,display_id,display_order,access_tier,knowledge_type,quotation,provenance)
 values('theory-8bc430c4-f80e-4e74-bb04-aca4a0d9c8bf','友情と欠点の指摘','自己開示よりも、相手が受け入れにくい指摘を伝える難しさを突く。相手を裁く口実ではなく、友情の配慮と率直さの緊張を読む。','classics-thought','古典・思想','classics-thought-p',25,'theory-8bc430c4-f80e-4e74-bb04-aca4a0d9c8bf','[]','[]','[]','published',89,89,'complete','aphorism','{"candidateId":"46","originalText":"Le plus grand effort de l’amitié n’est pas de montrer nos défauts à un ami, c’est de lui faire voir les siens.","translationText":"友情のいちばん難しい仕事は、自分の欠点を見せることではなく、友人にその人自身の欠点を気づかせることだ。","author":"ラ・ロシュフコー","authorDeathYear":1680,"work":"箴言集","locator":"第432箴言（1817年版。版によって番号が異なる）","publicationYear":1817,"originalLanguage":"fr","translationKind":"independent_translation","verification":"verified","rightsStatus":"cleared","rightsBasis":"著者1680年没、原語作品は1817年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","sourceUrls":["https://fr.wikisource.org/wiki/Maximes_et_Réflexions_morales/Réflexions_morales"],"checkedOn":"2026-10-15","contextNote":"自己開示よりも、相手が受け入れにくい指摘を伝える難しさを突く。相手を裁く口実ではなく、友情の配慮と率直さの緊張を読む。"}'::jsonb,'{"status":"確認済み","attribution":"ラ・ロシュフコー","period":"1817年（原典・参照版）","works":["箴言集"],"sources":[{"title":"箴言集（原典本文）","url":"https://fr.wikisource.org/wiki/Maximes_et_Réflexions_morales/Réflexions_morales"}],"note":"原語本文を照合した独自訳。 文学的・思想的な洞察であり、実証的な証拠とは区別する。"}'::jsonb);
insert into public.theories(id,title,summary,category_id,category_title,subcategory_id,taxonomy_order,canonical_id,legacy_ids,aliases,related_theory_ids,status,display_id,display_order,access_tier,knowledge_type,quotation,provenance)
 values('theory-a70e3a53-86c5-45e0-afb4-97e081936b53','貸した金と失う友','貸した金だけでなく友情まで失う二重の損失を、父が子へ戒める台詞。作者の金融理論や、あらゆる借入れを禁じる普遍規則ではない。','classics-thought','古典・思想','classics-thought-f',15,'theory-a70e3a53-86c5-45e0-afb4-97e081936b53','[]','[]','[]','published',90,90,'complete','aphorism','{"candidateId":"49","originalText":"Neither a borrower nor a lender be: For loan oft loses both itself and friend;","translationText":"借り手にも貸し手にもなるな。貸せば、金も友も失いがちだから。","author":"シェイクスピア","authorDeathYear":1616,"work":"ハムレット","locator":"第1幕第3場、ポローニアスがレアティーズへ語る台詞","publicationYear":1603,"originalLanguage":"en","translationKind":"independent_translation","verification":"verified","rightsStatus":"cleared","rightsBasis":"著者1616年没、原語作品は1603年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","sourceUrls":["https://www.gutenberg.org/cache/epub/1524/pg1524.txt"],"checkedOn":"2026-10-15","contextNote":"貸した金だけでなく友情まで失う二重の損失を、父が子へ戒める台詞。作者の金融理論や、あらゆる借入れを禁じる普遍規則ではない。"}'::jsonb,'{"status":"確認済み","attribution":"シェイクスピア","period":"1603年（原典・参照版）","works":["ハムレット"],"sources":[{"title":"ハムレット（原典本文）","url":"https://www.gutenberg.org/cache/epub/1524/pg1524.txt"}],"note":"原語本文を照合した独自訳。 文学的・思想的な洞察であり、実証的な証拠とは区別する。"}'::jsonb);
