insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('01','{"candidateId":"01","collection":"QUIZ BANG","collectionUrl":"https://www.quizbang.net/read/listen_trivia/24254/","author":"パスツール","deathYear":1895,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"偶然は準備していない者を助けない","connection":"準備・機会","originalText":"dans les champs de l’observation le hasard ne favorise que les esprits préparés","displayText":"観察の場では、偶然は準備のできた心だけに味方する。","work":"ドゥエーでの演説","locator":"1854年12月7日、科学教育と発見を論じた箇所","publicationYear":1854,"originalLanguage":"fr","primaryUrl":"https://www.centraliens-lille.org/fr/article/louis-pasteur-et-l-ecole-discours-du-7-decembre-1854-aux-les-jeunes-gens-destines-a-la-carriere-industrielle/23/11/2014/131","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1895年没、原語作品は1854年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"update_existing","reason":"既存「準備された心」kb_595を原文付きの格言として再編集。新規重複を作らない。","duplicateReview":"既存kb_595「準備された心」と同じ原典・主題。安定ID・表示ID・アクセス範囲を保ったまま再編集。","relatedTechniqueIds":["master336-334"],"relatedTheoryIds":["kb_593","kb_552"],"theoryId":"kb_595","alternative":null,"checkedOn":"2026-10-15","researchQueries":["パスツール 偶然は準備していない者を助けない 原典","パスツール 準備・機会 原文 source"],"additionalSources":["https://research.pasteur.fr/wp-content/uploads/2023/09/research_pasteur-encenter-for-technological-resources-and-researchfrcentre-de-ressources-et-recherches-technologiques-dt-brochure-technological-training-v3-planches.pdf"],"summary":"偶然の発見を、知識や問題意識を持つ人が見抜くという言葉。準備が幸運そのものを生むと証明する法則ではない。","subcategoryId":"classics-thought-p","displayTitle":"準備された心","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'kb_595');
