insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('13','{"candidateId":"13","collection":"名言集.com：小説家","collectionUrl":"https://www.meigensyu.com/professions/novelist/quotes","author":"太宰治","deathYear":1948,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"大人とは裏切られた青年の姿である","connection":"理想と現実・成熟","originalText":"大人とは、裏切られた青年の姿である。","displayText":"大人とは、裏切られた青年の姿である。","work":"津軽","locator":"人をあてにできなくなる「大人への第一課」を語る箇所","publicationYear":1944,"originalLanguage":"ja","primaryUrl":"https://www.aozora.gr.jp/cards/000035/files/2282_15074.html","originalVerification":"原典本文と照合済み（権利条件は保留）","translationReview":"著者の日本語原文を使用。表記整理した箇所は原文を別記。現代の解説・校注は転載しない。","rightsReview":"著者1948年没。日本語原著は1944年までに公表済み。旧法の死後50年期間が2018年以前に満了し復活しない。日本著作物のため戦時加算なし。底本の新しい解説・校注を使用しない。 米国の外国著作物の復活保護（Copyright Office Circular 38B）と配信地域を追加確認するまで公開しない。","decision":"hold","reason":"日本では原典の保護期間満了を確認。原文・帰属も照合済みだが、1942/1944年公表作品について米国等の配信先での復活著作権・保護期間の扱いを確認できないため、今回の公開は保留。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-105"],"relatedTheoryIds":[],"theoryId":null,"alternative":null,"checkedOn":"2026-10-15","researchQueries":["太宰治 大人とは裏切られた青年の姿である 原典","太宰治 理想と現実・成熟 原文 source"],"summary":"理想を裏切られ、用心を覚える大人の姿を凝縮した言葉。成熟には必ず裏切りが必要だとする発達理論ではない。","subcategoryId":"classics-thought-f","displayTitle":null,"publicationConditions":"原典本文・箇所・帰属・初出・利用地域の権利と独自訳が揃うまで非公開"}'::jsonb,null);
