insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('17','{"candidateId":"17","collection":"名言集.com：小説家","collectionUrl":"https://www.meigensyu.com/professions/novelist/quotes","author":"ゲーテ","deathYear":1832,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"最大の罪は不機嫌である","connection":"感情の社会的影響","originalText":"und du weißt, das ist die Sünde, die ich ärger hasse am Menschen als alle andre.","displayText":"人間の罪のなかで、私が何より憎むのは不機嫌だ。","work":"若きウェルテルの悩み","locator":"第1部、7月30日の書簡。ウェルテルがアルベルトの気質を語る箇所","publicationYear":1774,"originalLanguage":"de","primaryUrl":"https://www.gutenberg.org/cache/epub/2407/pg2407-images.html","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1832年没、原語作品は1774年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-350"],"relatedTheoryIds":["kb_023"],"theoryId":"theory-62543145-f91d-448d-aece-2a44802164f8","alternative":null,"checkedOn":"2026-10-15","researchQueries":["ゲーテ 最大の罪は不機嫌である 原典","ゲーテ 感情の社会的影響 原文 source"],"summary":"候補の「最大の罪」は、原文では語り手が最も憎む罪という主観的表現。周囲へ及ぶ機嫌の影響を読む台詞で、作者による道徳の順位表ではない。","subcategoryId":"classics-thought-f","displayTitle":"不機嫌という罪","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-62543145-f91d-448d-aece-2a44802164f8');
