insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('19','{"candidateId":"19","collection":"名言集.com：小説家","collectionUrl":"https://www.meigensyu.com/professions/novelist/quotes","author":"ゲーテ","deathYear":1832,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"苦難を知らなければ人生の味は分からない","connection":"苦難・理解","originalText":"Wer nie sein Brod mit Thränen as, Wer nie die kummervollen Nächte Auf seinem Bette weinend sas, Der kennt euch nicht, ihr himmlischen Mächte.","displayText":"涙でパンを食べたことも、悲しみの夜を寝台で泣いて過ごしたこともない者は、天上の力であるあなたがたを知らない。","work":"ヴィルヘルム・マイスターの修業時代","locator":"竪琴弾きの歌「涙でパンを食べたことのない者は」、前半","publicationYear":1795,"originalLanguage":"de","primaryUrl":"https://de.wikisource.org/wiki/Wer_nie_sein_Brot_mit_Tränen_aß","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1832年没、原語作品は1795年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-311"],"relatedTheoryIds":[],"theoryId":"theory-a16caa2e-318b-4527-bd2a-0dfb9b6a1f33","alternative":null,"checkedOn":"2026-10-15","researchQueries":["ゲーテ 苦難を知らなければ人生の味は分からない 原典","ゲーテ 苦難・理解 原文 source"],"summary":"「人生の味」という流通する要約を、苦痛と天上の力を歌う原詩へ戻した。苦難を他者へ強いる教訓や、苦しみを幸福の必要条件とする主張ではない。","subcategoryId":"classics-thought-f","displayTitle":"涙で食べるパン","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-a16caa2e-318b-4527-bd2a-0dfb9b6a1f33');
