insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('25','{"candidateId":"25","collection":"名言集.com：小説家","collectionUrl":"https://www.meigensyu.com/professions/novelist/quotes","author":"太宰治","deathYear":1948,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"幸福の便りは待っているときに来ない","connection":"期待と幸福","originalText":"幸福の便りというものは、待っている時には、決して来ないものだ。","displayText":"幸福の便りというものは、待っている時には、決して来ないものだ。","work":"正義と微笑","locator":"6月4日・火曜日の日記","publicationYear":1942,"originalLanguage":"ja","primaryUrl":"https://www.aozora.gr.jp/cards/000035/files/1577_8581.html","originalVerification":"原典本文と照合済み（権利条件は保留）","translationReview":"著者の日本語原文を使用。表記整理した箇所は原文を別記。現代の解説・校注は転載しない。","rightsReview":"著者1948年没。日本語原著は1942年までに公表済み。旧法の死後50年期間が2018年以前に満了し復活しない。日本著作物のため戦時加算なし。底本の新しい解説・校注を使用しない。 米国の外国著作物の復活保護（Copyright Office Circular 38B）と配信地域を追加確認するまで公開しない。","decision":"hold","reason":"日本では原典の保護期間満了を確認。原文・帰属も照合済みだが、1942/1944年公表作品について米国等の配信先での復活著作権・保護期間の扱いを確認できないため、今回の公開は保留。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-252"],"relatedTheoryIds":["kb_601"],"theoryId":null,"alternative":null,"checkedOn":"2026-10-15","researchQueries":["太宰治 幸福の便りは待っているときに来ない 原典","太宰治 期待と幸福 原文 source"],"summary":"幸福を待ち受ける期待と、訪れる喜びのずれを描く作中日記の一節。待たなければ必ず幸福になるという因果法則ではない。","subcategoryId":"classics-thought-f","displayTitle":null,"publicationConditions":"原典本文・箇所・帰属・初出・利用地域の権利と独自訳が揃うまで非公開"}'::jsonb,null);
insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('26','{"candidateId":"26","collection":"名言集.com：小説家","collectionUrl":"https://www.meigensyu.com/professions/novelist/quotes","author":"芥川龍之介","deathYear":1927,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"恋愛は性欲の詩的表現","connection":"恋愛の理想化","originalText":"恋愛は唯性慾の詩的表現を受けたものである。少くとも詩的表現を受けない性慾は恋愛と呼ぶに価いしない。","displayText":"恋愛はただ性欲の詩的表現を受けたものである。","work":"侏儒の言葉","locator":"「恋愛」、冒頭2文のうち第1文を表記整理して表示","publicationYear":1927,"originalLanguage":"ja","primaryUrl":"https://www.aozora.gr.jp/cards/000879/files/158_15132.html","originalVerification":"原典本文と照合済み","translationReview":"著者の日本語原文を使用。表記整理した箇所は原文を別記。現代の解説・校注は転載しない。","rightsReview":"著者1927年没。日本語原著は1927年までに公表済み。旧法の死後50年期間が2018年以前に満了し復活しない。日本著作物のため戦時加算なし。底本の新しい解説・校注を使用しない。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":[],"relatedTheoryIds":[],"theoryId":"theory-e1df3caa-9877-4eed-a549-162cc3bdaca0","alternative":null,"checkedOn":"2026-10-15","researchQueries":["芥川龍之介 恋愛は性欲の詩的表現 原典","芥川龍之介 恋愛の理想化 原文 source"],"summary":"欲望が言葉や想像によって恋愛へ姿を変えるという、皮肉を含む見方。続く原文は、詩的表現を受けない性欲は恋愛と呼ぶに値しないと述べる。","subcategoryId":"classics-thought-f","displayTitle":"恋愛の詩的表現","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-e1df3caa-9877-4eed-a549-162cc3bdaca0');
insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('27','{"candidateId":"27","collection":"名言集.com：小説家","collectionUrl":"https://www.meigensyu.com/professions/novelist/quotes","author":"アルフレッド・ド・ミュッセ","deathYear":1857,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"恋は空腹で生き、満腹で死ぬ","connection":"欲望・恋愛心理","originalText":"L’amour (hélas ! l’étrange et la fausse nature !) Vit d’inanition, et meurt de nourriture.","displayText":"恋は飢えによって生き、食べ物を与えられて死ぬ。","work":"マルドッシュ（初期詩集）","locator":"第16節、末尾2行","publicationYear":1829,"originalLanguage":"fr","primaryUrl":"https://fr.wikisource.org/wiki/Premières_Poésies_(Musset,_éd._1863)/Mardoche","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1857年没、原語作品は1829年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-070"],"relatedTheoryIds":["kb_268"],"theoryId":"theory-acb4311e-b6ca-416c-8d06-06cff53444b2","alternative":null,"checkedOn":"2026-10-15","researchQueries":["アルフレッド・ド・ミュッセ 恋は空腹で生き、満腹で死ぬ 原典","アルフレッド・ド・ミュッセ 欲望・恋愛心理 原文 source"],"summary":"恋が満たされないことで続き、充足によって衰えるという逆説を詠む。恋愛相手を意図的に不安にさせる手法や、関係の普遍法則としては扱わない。","subcategoryId":"classics-thought-f","displayTitle":"恋の飢えと充足","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-acb4311e-b6ca-416c-8d06-06cff53444b2');
