insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('33','{"candidateId":"33","collection":"名言集.com：小説家","collectionUrl":"https://www.meigensyu.com/professions/novelist/quotes","author":"ドストエフスキー","deathYear":1881,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"幸福は発見ではなく、そこへ向かう過程にある","connection":"達成・幸福","originalText":"О, будьте уверены, что Колумб был счастлив не тогда, когда открыл Америку, а когда открывал ее;","displayText":"コロンブスが幸福だったのは、アメリカを発見したときではなく、発見しつつあったときだ。","work":"白痴","locator":"第3部第5章、イッポリートの「弁明」","publicationYear":1868,"originalLanguage":"ru","primaryUrl":"https://ru.wikisource.org/wiki/Идиот_(Достоевский)/Часть_III/Глава_V","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1881年没、原語作品は1868年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-252"],"relatedTheoryIds":["kb_268"],"theoryId":"theory-d15357a9-73da-4286-859e-91a7ebcb5f85","alternative":null,"checkedOn":"2026-10-15","researchQueries":["ドストエフスキー 幸福は発見ではなく、そこへ向かう過程にある 原典","ドストエフスキー 達成・幸福 原文 source"],"summary":"人生を発見し続ける過程へ目を向ける、作中人物の切迫した独白。コロンブスの実際の心理を史実として記録した文でも、達成後は必ず不幸になるという研究でもない。","subcategoryId":"classics-thought-f","displayTitle":"発見の途上にある幸福","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-d15357a9-73da-4286-859e-91a7ebcb5f85');
