insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('43','{"candidateId":"43","collection":"名言集.com：友情","collectionUrl":"https://www.meigensyu.com/categories/friendship","author":"モンテーニュ","deathYear":1592,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"友人を自分に引き寄せるより、自分を友人へ与える","connection":"相互性","originalText":"En la vraye amitié, de laquelle je suis expert, je me donne à mon amy plus que je ne le tire à moy.","displayText":"真の友情では、友を自分へ引き寄せる以上に、自分を友に与える。","work":"エセー","locator":"第3巻第9章「虚栄について」","publicationYear":1588,"originalLanguage":"fr","primaryUrl":"https://fr.wikisource.org/wiki/Page:Montaigne_-_Essais,_Éd_de_Bordeaux,_3.djvu/174","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1592年没、原語作品は1588年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-108"],"relatedTheoryIds":["kb_032"],"theoryId":"theory-4e128612-e3f0-4eb9-9c09-e3503466521d","alternative":null,"checkedOn":"2026-10-15","researchQueries":["モンテーニュ 友人を自分に引き寄せるより、自分を友人へ与える 原典","モンテーニュ 相互性 原文 source"],"summary":"友情を、相手を自分に従わせる関係とは反対のものとして語る。無制限な自己犠牲や、相手の要求をすべて引き受けることとは分けて読む。","subcategoryId":"classics-thought-p","displayTitle":"友に自分を与える","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-4e128612-e3f0-4eb9-9c09-e3503466521d');
insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('44','{"candidateId":"44","collection":"名言集.com：友情","collectionUrl":"https://www.meigensyu.com/categories/friendship","author":"ラ・ロシュフコー","deathYear":1680,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"友人を疑うことは、欺かれることより恥ずかしい","connection":"信頼・不信","originalText":"Il est plus honteux de se défier de ses amis que d’en être trompé.","displayText":"友人を疑うことは、友人にだまされることより恥ずかしい。","work":"箴言集","locator":"第84箴言（1817年版）","publicationYear":1817,"originalLanguage":"fr","primaryUrl":"https://fr.wikisource.org/wiki/Maximes_et_Réflexions_morales/Réflexions_morales","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1680年没、原語作品は1817年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-105"],"relatedTheoryIds":["kb_424"],"theoryId":"theory-8cd3b27e-6948-4ad0-b961-46eb047b1b67","alternative":null,"checkedOn":"2026-10-15","researchQueries":["ラ・ロシュフコー 友人を疑うことは、欺かれることより恥ずかしい 原典","ラ・ロシュフコー 信頼・不信 原文 source"],"summary":"裏切られる損より、疑いによって友情を損なう恥を強く置いた箴言。相手の危険な言動を無視する指示や、無条件の信用を証明する理論ではない。","subcategoryId":"classics-thought-p","displayTitle":"友情における疑い","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-8cd3b27e-6948-4ad0-b961-46eb047b1b67');
