insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('49','{"candidateId":"49","collection":"名言集.com：友情","collectionUrl":"https://www.meigensyu.com/categories/friendship","author":"シェイクスピア","deathYear":1616,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"金の貸し借りによって友情を失う","connection":"金銭・人間関係","originalText":"Neither a borrower nor a lender be: For loan oft loses both itself and friend;","displayText":"借り手にも貸し手にもなるな。貸せば、金も友も失いがちだから。","work":"ハムレット","locator":"第1幕第3場、ポローニアスがレアティーズへ語る台詞","publicationYear":1603,"originalLanguage":"en","primaryUrl":"https://www.gutenberg.org/cache/epub/1524/pg1524.txt","originalVerification":"原典本文と照合済み","translationReview":"権利満了の原語本文から、このアプリ向けに独自訳を作成。掲載サイトや既存の日本語訳は転載しない。","rightsReview":"著者1616年没、原語作品は1603年までに公表済み。日本の旧保護期間に戦時加算の最大約11年を安全側に加えても2018年より前に満了し、延長による復活なし。原語本文のみ使用し現代の翻訳・編集文を除外。日本語は独自訳。","decision":"adopt","reason":"原典・帰属・権利・独自訳を確認し採用。","duplicateReview":"既存の金銭・境界線の理論と主題は重なるが、ポローニアスの台詞としての文学的役割が異なり独立収録。","relatedTechniqueIds":[],"relatedTheoryIds":["kb_092"],"theoryId":"theory-a70e3a53-86c5-45e0-afb4-97e081936b53","alternative":null,"checkedOn":"2026-10-15","researchQueries":["シェイクスピア 金の貸し借りによって友情を失う 原典","シェイクスピア 金銭・人間関係 原文 source"],"summary":"貸した金だけでなく友情まで失う二重の損失を、父が子へ戒める台詞。作者の金融理論や、あらゆる借入れを禁じる普遍規則ではない。","subcategoryId":"classics-thought-f","displayTitle":"貸した金と失う友","publicationConditions":"原典と独自訳を保持し、著名人の言葉を実証的証拠として表示しない"}'::jsonb,'theory-a70e3a53-86c5-45e0-afb4-97e081936b53');
insert into public.theory_quote_reviews(candidate_id,audit,theory_id) values('50','{"candidateId":"50","collection":"名言集.com：友情","collectionUrl":"https://www.meigensyu.com/categories/friendship","author":"ジョージ・ムーア","deathYear":1933,"deathYearNote":"候補人物の没年。単独では利用許諾の根拠にしない。","candidateText":"恋人がいる人に友情を与えるのは、渇いた人にパンを渡すようなもの","connection":"相手の欲求理解","originalText":null,"displayText":null,"work":null,"locator":null,"publicationYear":null,"originalLanguage":null,"primaryUrl":null,"originalVerification":"未確認","translationReview":"サイト掲載訳は転載しない。原文を確認できるまで公開訳を作成しない。","rightsReview":"原典・初出・翻訳区分を確定できないため、死亡年だけでは公開可と判定しない。","decision":"hold","reason":"掲載元の「恋人のいる人間」と、流通英語の「愛情を求める相手」に意味のずれがある。ムーアの原典・初出を確定できず公開保留。","duplicateReview":"既存803件のタイトル・概要と照合。主題が似る科学理論とは役割を分け、機械的な統合は行わない。","relatedTechniqueIds":["master336-059"],"relatedTheoryIds":[],"theoryId":null,"alternative":null,"checkedOn":"2026-10-15","researchQueries":["ジョージ・ムーア 恋人がいる人に友情を与えるのは、渇いた人にパンを渡すようなもの 原典","ジョージ・ムーア 相手の欲求理解 原文 source"],"displayTitle":null,"publicationConditions":"原典本文・箇所・帰属・初出・利用地域の権利と独自訳が揃うまで非公開"}'::jsonb,null);
-- Closing archive gaps changes only sorting positions, never displayed/stable IDs.
with ranked as(select id,row_number() over(partition by subcategory_id order by taxonomy_order,display_id,id)::integer position from public.theories where status='published')
update public.theories t set taxonomy_order=r.position from ranked r where t.id=r.id and t.taxonomy_order is distinct from r.position;
-- Retain the six major and thirty-six internal identities. Only names/order may be edited.
create function public.preserve_theory_taxonomy() returns trigger language plpgsql set search_path='' as $fn$
begin
 if tg_table_name='theory_subcategories' then
  if tg_op<>'UPDATE' then raise exception '既存36内部分類を維持します。追加・分割・削除はできません。' using errcode='23514';end if;
  if (new.id,new.category_id) is distinct from (old.id,old.category_id) then raise exception '内部分類のID・大分類は変更できません。' using errcode='23514';end if;
 else
  if tg_op='INSERT' and new.kind='theory' or tg_op='DELETE' and old.kind='theory' then raise exception '理論の6大分類を維持します。' using errcode='23514';end if;
  if tg_op='UPDATE' and (new.kind='theory' or old.kind='theory') and (new.id,new.kind) is distinct from (old.id,old.kind) then raise exception '理論の大分類IDは変更できません。' using errcode='23514';end if;
 end if;
 if tg_op='DELETE' then return old;else return new;end if;
end $fn$;
revoke all on function public.preserve_theory_taxonomy() from public,anon,authenticated;
create trigger preserve_theory_subcategories before insert or update or delete on public.theory_subcategories for each row execute function public.preserve_theory_taxonomy();
create trigger preserve_theory_categories before insert or update or delete on public.content_categories for each row execute function public.preserve_theory_taxonomy();
do $verify$ begin
 if (select count(*) from public.theories where status='published')<>821 then raise exception 'Unexpected final theory count';end if;
 if (select count(*) from public.theory_subcategories)<>36 or (select count(*) from public.content_categories where kind='theory')<>6 then raise exception 'Taxonomy changed';end if;
 if (select count(*) from public.theory_quote_reviews)<>50 then raise exception 'Missing candidate audits';end if;
 if (select count(*) from public.theories where status='published' and quotation is not null)<>19 then raise exception 'Unreviewed quote appeared';end if;
end $verify$;
